fn find_minimum_total_distance(x1: i8, x2: i8, x3: i8) -> i8 {
    // The minimum total distance to move three points to a single point on a line
    // is achieved by choosing the median of the three points.
    // This is a well-known property minimizing sum of absolute distances.

    let mut points = [x1, x2, x3];
    points.sort_unstable();
    let median = points[1]; // the middle element after sorting

    // sum of absolute distances to median
    let total_distance = (x1 - median).abs() + (x2 - median).abs() + (x3 - median).abs();

    total_distance
}